 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    cut = next(c for c in range(w) if all(row[c] == 0 for row in grid))
    left = {v for row in grid for v in row[:cut]}
    right = [row[cut+1:] for row in grid]
    shared = left & {v for row in right for v in row}
    bg = next(iter(shared))
    return [[bg if v == bg else 3 for v in row] for row in right]
